const char* WIFI_SSID = "YOUR_WIFI_NAME";
const char* WIFI_PASSWORD = "YOUR_WIFI_PASSWORD";
const char* CHANNEL_ID = "3594258";
const char* READ_API_KEY = "XKXDZN01ERL8CVHX";

Adafruit_SSD1306 display(128, 64, &Wire, -1);
unsigned long lastRead = 0;
const unsigned long READ_INTERVAL = 20000;

void connectWiFi() {
  WiFi.mode(WIFI_STA);
  WiFi.begin(WIFI_SSID, WIFI_PASSWORD);
  while (WiFi.status() != WL_CONNECTED) delay(500);
}

void readAndShowDHT() {
  String url = "http://api.thingspeak.com/channels/";
  url += CHANNEL_ID;
  url += "/feeds/last.json?api_key=";
  url += READ_API_KEY;

  HTTPClient http;
  http.begin(url);
  int code = http.GET();
  String body = http.getString();
  http.end();

  StaticJsonDocument<512> doc;
  if (code != 200 || deserializeJson(doc, body) ||
      doc["field1"].isNull() || doc["field2"].isNull()) {
    display.clearDisplay();
    display.setCursor(0, 20);
    display.println("No DHT readings");
    display.display();
    return;
  }

  float temperature = doc["field1"].as<String>().toFloat();
  float humidity = doc["field2"].as<String>().toFloat();

  display.clearDisplay();
  display.setTextColor(SSD1306_WHITE);
  display.setTextSize(1);
  display.setCursor(0, 5);
  display.println("DHT22 from ThingSpeak");
  display.setTextSize(2);
  display.setCursor(0, 22);
  display.printf("T: %.1f C", temperature);
  display.setCursor(0, 45);
  display.printf("H: %.1f%%", humidity);
  display.display();

  Serial.printf("Temperature: %.1f C, humidity: %.1f%%\n",
                temperature, humidity);
}

void setup() {
  Serial.begin(115200);
  Wire.begin(21, 22);
  display.begin(SSD1306_SWITCHCAPVCC, 0x3C);
  connectWiFi();
  readAndShowDHT();
  lastRead = millis();
}

void loop() {
  if (millis() - lastRead >= READ_INTERVAL) {
    lastRead = millis();
    readAndShowDHT();
  }
}

