#define RED_LED_PIN 18
#define GREEN_LED_PIN 19
#define BUZZER_PIN 23

const int SOIL_DRY_RAW = 3000;
const int SOIL_WET_RAW = 1300;
const float MIN_GOOD_SOIL_PERCENT = 30.0;
const int LIGHT_DETECTED_LEVEL = LOW;  // Active-low comparator

void readAndControl() {
  // 1. Fetch JSON from ThingSpeak Field 3 (Soil) & Field 4 (LDR)
  // ... HTTP GET code ...
  int soilRaw = doc["field3"].as<String>().toInt();
  int ldrRaw = doc["field4"].as<String>().toInt();

  // 2. Calibrate Soil Moisture Percentage
  float soilPercent = (float)(SOIL_DRY_RAW - soilRaw) * 100.0 / (float)(SOIL_DRY_RAW - SOIL_WET_RAW);
  soilPercent = constrain(soilPercent, 0.0, 100.0);
  bool lightDetected = (ldrRaw == LIGHT_DETECTED_LEVEL);

  // 3. Evaluate Boolean Decision Rule
  bool good = (soilPercent >= MIN_GOOD_SOIL_PERCENT) && lightDetected;

  // 4. Actuate Physical Indicators
  digitalWrite(RED_LED_PIN, good ? LOW : HIGH);
  digitalWrite(GREEN_LED_PIN, good ? HIGH : LOW);
  digitalWrite(BUZZER_PIN, good ? LOW : HIGH);  // Active buzzer alerts!

  // 5. Update Local OLED Status
  display.clearDisplay();
  display.setCursor(0, 2); display.println("Soil and light status");
  display.setTextSize(2);
  display.setCursor(0, 16); display.printf("Soil: %.0f%%", soilPercent);
  display.setTextSize(1);
  display.setCursor(0, 40); display.printf("Raw: %d Light: %s", soilRaw, lightDetected ? "YES" : "NO");
  display.setCursor(0, 54); display.print("Status: "); display.println(good ? "GOOD" : "CHECK");
  display.display();
}

